source=Path('results/spoon-right-physical-049');out=Path('results/spoon-grasp-acceptance-001');out.mkdir(exist_ok=False);shutil.copy2(__file__,out/Path(__file__).name);r=json.loads((source/'report.json').read_text());s=G1Sim(r['scene']);m,d=s.m,s.d;ck=np.load(source/'continuation.npz');mujoco.mj_setState(m,d,ck['integration'],mujoco.mjtState.mjSTATE_INTEGRATION);mujoco.mj_forward(m,d);palm_above=float(d.xpos[m.body('right_wrist_yaw_link').id,2]-d.xpos[m.body('scoop').id,2]);tilt=float(np.rad2deg(np.arccos(d.xmat[m.body('scoop').id].reshape(3,3)[2,2])));peak_ok=all(v<=m.actuator_ctrlrange[s.act_joint[n],1]+1e-10 for n,v in r['peak_motor_torques_Nm'].items());checks={'executor_pass':r['pass'],'original15deg_rotation_also_met':r['max_grasp_relative_rotation_deg']<15,'original0_5N_tip_limit_also_met':r['tip_contact_peak_N']<=.5,'hold_position_under2mm':r['hold_drift_m']<.002,'hold_angle_under2deg':r['hold_angle_drift_deg']<2,'palm_above45mm':palm_above>.045,'tilt_under10deg':tilt<10,'lift_over50mm':r['max_spoon_lift_m']>.05,'motor_limits':bool(peak_ok),'no_warnings':r['warnings']==0,'no_water_spill':r['water_state']['spilled_ml']==0};result={'model':'gpt-6-astra','source':str(source),'pass':all(checks.values()),'checks':checks,'palm_above_spoon_m':palm_above,'final_tilt_deg':tilt,'report_sha256':hashlib.sha256((source/'report.json').read_bytes()).hexdigest(),'scope':'saved execution metrics and final checkpoint; not hardware validation','coffee_completed':False};(out/'report.json').write_text(json.dumps(result,indent=2));print(result)
